using EqlTracker.Core;

static class SessionTests
{
    public static void Register(Action<string, Action> test)
    {
        void Check(bool value) { if (!value) throw new Exception("Session assertion failed"); }
        DateTime t = new(2026, 10, 17, 9, 0, 0);
        string Line(string message, int minute = 0) => $"[{t.AddMinutes(minute):ddd MMM dd HH:mm:ss yyyy}] {message}";
        SessionEvidence Evidence() { var e = new SessionEvidence(); e.Observe(Line("Welcome to EverQuest Legends!"), "file:0"); return e; }
        Encounter Fight(string id, int minute, long damage = 100) => new() { Id = id, Start = t.AddMinutes(minute), End = t.AddMinutes(minute).AddSeconds(10), Finished = true, PlayerDamage = damage, Events = [new() { Id = id, Time = t.AddMinutes(minute), Owner = "Player", Actor = "Rune", Target = "orc", Kind = "Melee", Ability = "slashes", Damage = damage }] };
        test("Login sessions survive zone and cancelled camp", () => { var e = Evidence(); e.Observe(Line("You have entered East Freeport.", 1), "file:30"); e.Observe(Line("It will take you about 30 seconds to prepare your camp.", 2), "file:80"); e.Observe(Line("You slash an orc.", 3), "file:90"); Check(e.Sessions.Count == 1 && e.Sessions[0].LastObserved == t.AddMinutes(3) && e.Sessions[0].NextLogin == null); });
        test("Each login creates a session without merging reconnects", () => { var e = Evidence(); e.Observe(Line("Welcome to EverQuest Legends!", 4), "file:100"); Check(e.Sessions.Count == 2 && e.Sessions[0].NextLogin == t.AddMinutes(4)); });
        test("Duplicate login evidence is idempotent", () => { var e = Evidence(); e.Observe(Line("Welcome to EverQuest Legends!"), "file:0"); Check(e.Sessions.Count == 1); });
        test("Missing login produces explicit inferred evidence", () => { var e = new SessionEvidence(); e.Observe(Line("You have entered East Freeport."), "file:2"); Check(e.Sessions.Single().Inferred); });
        test("Rotated logs preserve older sessions", () => { var e = Evidence(); e.Observe(Line("You hit an orc.", 10), "rotated:0"); Check(e.Sessions.Count == 2 && e.Sessions[1].Inferred && e.Sessions[0].NextLogin.HasValue); });
        test("Class identity normalizes equivalent ordering", () => Check(SessionEvidence.Normalize(["shd", "MAG", "BRD"]) == "BRD/MAG/SHD"));
        test("Classes remain unknown before verified observation", () => { var e = Evidence(); e.ObserveDetails(new() { Time = t.AddMinutes(2), Classes = ["SHD", "MAG", "BRD"] }, "file:5", "/who"); Check(SessionEvidence.ClassesFor(e.Sessions[0], Fight("early", 1)) == "Unknown"); Check(SessionEvidence.ClassesFor(e.Sessions[0], Fight("late", 3)) == "BRD/MAG/SHD"); });
        test("Conflicting in-fight classes stay Mixed", () => { var e = Evidence(); var s = e.Sessions[0]; s.Classes = [new("a", t, "BRD/MAG/SHD", "", "verified"), new("b", t.AddMinutes(1).AddSeconds(5), "CLR/MAG/WAR", "", "verified")]; Check(SessionEvidence.ClassesFor(s, Fight("mix", 1)) == "Mixed"); });
        test("Repeated who observations do not create Mixed", () => { var e = Evidence(); var s = e.Sessions[0]; s.Classes = [new("a", t, "MAG/SHD", "", "who"), new("b", t.AddMinutes(1).AddSeconds(5), "MAG/SHD", "", "who")]; Check(SessionEvidence.ClassesFor(s, Fight("same", 1)) == "MAG/SHD"); });
        test("Session selection retains original combat denominators", () => { var e = Evidence(); e.Observe(Line("Welcome to EverQuest Legends!", 5), "file:50"); var fights = new[] { Fight("a", 1), Fight("b", 6) }; var v = DpsViews.Build(fights, null, DateTime.Now, new() { Scope = "Session", SessionId = e.Sessions[0].Id, Actor = "Combined" }, e.Sessions); Check(v.Fights.Count == 1 && v.Damage == 100 && v.Seconds == 10); });
        test("Offline latest session uses retained data rather than tracker launch", () => { var e = Evidence(); var v = DpsViews.Build([Fight("old", 1)], null, DateTime.Now, new() { Scope = "Session", Actor = "Combined" }, e.Sessions); Check(v.Damage == 100 && v.Session?.Id == "file:0"); });
        test("Class filter allocates encounters once", () => { var e = Evidence(); e.Sessions[0].Classes = [new("a", t, "MAG/SHD", "", "who"), new("b", t.AddMinutes(5), "CLR/WAR", "", "who")]; var a = Fight("a", 1); var b = Fight("b", 6); var v = DpsViews.Build([a, b], null, t, new() { Scope = "Session", Actor = "Combined", ClassCombinations = ["MAG/SHD"] }, e.Sessions); Check(v.Fights.Count == 1 && v.Seconds == 10 && v.Damage == 100 && a.Duration == 10 && b.Duration == 10); });
        test("Group includes known session members without combat", () => { var e = Evidence(); var s = e.Sessions[0]; s.LastObserved = t.AddMinutes(10); var p = new CharacterProfile { Character = "Rune", Meter = new() { Scope = "Session" }, GroupMembers = [new() { Name = "Friend", From = t.AddMinutes(3), Until = t.AddMinutes(4) }] }; var view = DpsViews.Build([Fight("a", 1)], null, t, p.Meter, e.Sessions); var group = CombatInspection.Build(view, null, p, [], new Dictionary<string, SpellReference>(), "group", false, "fixture"); Check(group.Members.Any(m => m.Name == "Friend" && m.Total == null)); });
        test("Session storage and checkpoints restart atomically", () => { string dir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N")); var e = Evidence(); e.Checkpoint = new() { Offset = 123, Generation = "file" }; using (var db = new TrackerStore(Path.Combine(dir, "data.db"))) db.SaveSessionEvidence(e); using (var db = new TrackerStore(Path.Combine(dir, "data.db"))) { var saved = db.Get<SessionEvidence>("sessionEvidence")!; Check(saved.Checkpoint?.Offset == 123 && saved.Sessions.Single().Id == "file:0"); } });
        test("Session range loads beyond initial encounter page", () => { string dir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString("N")); using var db = new TrackerStore(Path.Combine(dir, "data.db")); db.SaveEncounter(Fight("old", 1)); db.SaveEncounter(Fight("new", 10)); Check(db.LoadEncounters(limit: 1).Single().Id == "new"); Check(db.LoadEncounters(limit: int.MaxValue, from: t, until: t.AddMinutes(5)).Single().Id == "old"); });
        test("A login projection never clips an existing encounter duration", () => { var e = Evidence(); e.Observe(Line("Welcome to EverQuest Legends!", 2), "file:50"); var f = Fight("cross", 1); f.End = t.AddMinutes(3); var v = DpsViews.Build([f], null, t, new() { Scope = "Session", SessionId = e.Sessions[0].Id, Actor = "Combined" }, e.Sessions); Check(v.Seconds == 120 && f.Duration == 120); });
        test("Routine log activity does not invalidate session combat structure", () => { var e = Evidence(); long revision = e.ContentRevision; e.Observe(Line("Somebody says hello.", 1), "file:20"); Check(e.ContentRevision == revision && e.Revision > revision); });
        test("Manual class correction is bounded and does not hide underlying evidence", () => { var e = Evidence(); var session = e.Sessions[0]; session.Classes = [new("who", t, "MAG/SHD", "", "Character /who record"), new("manual", t.AddMinutes(1), "MNK/WAR", "", "Manual correction") { Until = t.AddMinutes(2) }]; Check(SessionEvidence.ClassesAt(session, t.AddSeconds(30)) == "MAG/SHD" && SessionEvidence.ClassesAt(session, t.AddSeconds(90)) == "MNK/WAR" && SessionEvidence.ClassesAt(session, t.AddMinutes(3)) == "MAG/SHD"); });
        test("Martial kick requires Self evidence at event time", () => { var e = Evidence(); e.Sessions[0].Classes = [new("who", t, "MNK/WAR", "", "who")]; var f = Fight("a", 1); f.Events[0].Ability = "kicks"; var v = DpsViews.Build([f], null, t, new() { Actor = "Combined" }, e.Sessions); Check(v.Rows.Single().MonkKick); f.Events[0].Owner = "Pet"; v = DpsViews.Build([f], null, t, new() { Actor = "Combined" }, e.Sessions); Check(!v.Rows.Single().MonkKick); });
        test("Export records session and class filters without new timing", () => { var e = Evidence(); var p = new CharacterProfile { Meter = new() { Scope = "Session", Actor = "Combined", ClassCombinations = ["Unknown"] } }; var v = DpsViews.Build([Fight("a", 1)], null, t, p.Meter, e.Sessions); var export = EncounterExporter.Snapshot(v, p); Check(export.SessionId == "file:0" && export.Seconds == 10 && export.ClassCombinations.SequenceEqual(new[] { "Unknown" })); });
    }
}
